import java.util.Arrays;

class Solution {
    public int maxValue(int[][] events, int k) {
        Arrays.sort(events, (a, b) -> Integer.compare(a[1], b[1]));
        int n = events.length;
        int[] ends = new int[n];
        for (int i = 0; i < n; ++i) ends[i] = events[i][1];
        int[][] dp = new int[n + 1][k + 1];

        for (int i = 1; i <= n; ++i) {
            int start = events[i - 1][0];
            int val = events[i - 1][2];
            int low = 0, high = n - 1, p = 0;
            while (low <= high) {
                int mid = (low + high) / 2;
                if (ends[mid] < start) {
                    p = mid + 1;
                    low = mid + 1;
                } else {
                    high = mid - 1;
                }
            }
            for (int j = 1; j <= k; ++j) {
                dp[i][j] = Math.max(dp[i - 1][j], dp[p][j - 1] + val);
            }
        }
        return dp[n][k];
    }
}

