var maxValue = function(events, k) {
    events.sort((a, b) => a[1] - b[1]);
    const n = events.length;
    const ends = events.map(e => e[1]);
    const dp = Array.from({ length: n + 1 }, () => Array(k + 1).fill(0));

    for (let i = 1; i <= n; ++i) {
        const start = events[i - 1][0];
        const val = events[i - 1][2];
        let low = 0, high = n - 1, p = 0;
        while (low <= high) {
            const mid = Math.floor((low + high) / 2);
            if (ends[mid] < start) {
                p = mid + 1;
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }
        for (let j = 1; j <= k; ++j) {
            dp[i][j] = Math.max(dp[i - 1][j], dp[p][j - 1] + val);
        }
    }
    return dp[n][k];
};
